begin;
set local request.jwt.claims='{"aal":"aal2"}';
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000901','import-admin@example.test'),('00000000-0000-4000-8000-000000000902','import-accounting@example.test'),('00000000-0000-4000-8000-000000000903','import-staff@example.test');
update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000000901';
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000902';
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000000903';
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000901';
select lives_ok($$select public.start_import_batch('00000000-0000-4000-8000-000000000910','performance','synthetic.xlsx',repeat('a',64),100)$$,'admin prepares historical dataset');
select is((select count(*) from public.import_batches where id='00000000-0000-4000-8000-000000000910'),1::bigint,'admin reads batch');
select throws_ok($$insert into public.import_batches(kind,file_name,file_sha256,storage_path,size_bytes) values('orders','bad.xlsx',repeat('b',64),'bad',100)$$,'42501',null,'direct batch writes revoked');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'orders','bad.xlsm',repeat('b',64),100)$$,'23514',null,'SQL disallows macro extension');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'orders','large.xlsx',repeat('b',64),10485761)$$,'23514',null,'SQL enforces file size');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'orders','bad.xlsx','bad',100)$$,'23514',null,'SQL validates hash');
select lives_ok($$insert into storage.objects(bucket_id,name,metadata) values('imports','00000000-0000-4000-8000-000000000910.xlsx','{"size":100,"mimetype":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}')$$,'owner can upload prepared object');
select throws_ok($$insert into storage.objects(bucket_id,name) values('imports','unlinked.xlsx')$$,'42501',null,'unlinked import upload blocked');
select throws_ok($$select * from app.import_changes$$,'42501',null,'rollback snapshots are private');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000902';
select is((select count(*) from public.import_batches where id='00000000-0000-4000-8000-000000000910'),0::bigint,'accounting cannot read historical personal dataset');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'orders','orders.xlsx',repeat('c',64),100)$$,'42501',null,'accounting cannot import orders');
select lives_ok($$select public.start_import_batch('00000000-0000-4000-8000-000000000911','budgets','budgets.csv',repeat('c',64),100)$$,'accounting may prepare budgets only');
select is((select count(*) from public.import_batches where id='00000000-0000-4000-8000-000000000911'),1::bigint,'accounting reads budget batch');
select is((select count(*) from storage.objects where bucket_id='imports' and name='00000000-0000-4000-8000-000000000910.xlsx'),0::bigint,'accounting cannot read original historical file');
select throws_ok($$select public.fail_import_upload('00000000-0000-4000-8000-000000000910')$$,'42501',null,'accounting cannot mutate foreign batch');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000903';
select is((select count(*) from public.import_batches where id in('00000000-0000-4000-8000-000000000910','00000000-0000-4000-8000-000000000911')),0::bigint,'staff cannot read imports');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'budgets','budgets.csv',repeat('d',64),100)$$,'42501',null,'staff cannot start import');
reset role;
select is((select public from storage.buckets where id='imports'),false,'import bucket is private');
select ok(exists(select 1 from pg_extension where extname='pg_trgm'),'similarity extension exists');
select ok(exists(select 1 from public.audit_log where table_name='import_batches' and record_id='00000000-0000-4000-8000-000000000910'),'batch creation audit transactional');
select * from finish();rollback;
